head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > readOnlyClass]<br/>Body Cell 이 읽기전용(readonly) 상태일때 적용할 CSS 클래스를 설정합니다.",
    "validation" : [
        "Body Cell 이 읽기전용(readonly) 상태일때 적용할 CSS 클래스를 설정합니다.",
        "초기 렌더링 시 readOnly 속성이 true 로 설정된 경우에 적용됩니다.",
        "CSS 파일이나 style 블럭에 정의된 클래스 이름을 공백으로 구분하여 설정합니다.",
        "값을 설정하지 않으면 'w2grid_default_readonly' 클래스가 적용됩니다.",
        "메소드를 사용하여 읽기전용(readonly) 상태를 변경한 경우엔 적용되지 않습니다.",
        "readOnlyClass 속성을 설정하면 기본값인 'w2grid_default_readonly' 클래스와 함께 적용됩니다.",
        "읽기전용(readonly) 상태가 해제되면 적용된 CSS 클래스가 제거됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정
    con_readOnlyClass.setSelectedIndex(1);

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 조건 설정
    //  - readOnlyClass 는 Body Column 단위 속성이므로 gridView XML 을 직접 구성하여 Column 별로 다르게 부여한다.
    //  - col1 : 초기 렌더링 시 readOnly="true" + readOnlyClass 설정        → @description|, @spec2
    //  - col2 : 초기 렌더링 시 readOnly="true" + readOnlyClass 미설정      → @propval| (기본 클래스)
    //  - col3 : 초기 readOnly 미설정 + readOnlyClass 설정 → 메소드(setColumnReadOnly)로 읽기전용 → @spec1
    //  - col4 : 초기 readOnly 미설정 + readOnlyClass 설정 → 메소드(setCellReadOnly)로 읽기전용   → @spec1
    let cClass = con_readOnlyClass.getValue();
    let lblClass = (cClass === '') ? '미설정' : cClass;
    let attrClass = (cClass === '') ? '' : ' readOnlyClass="' + cClass + '"';

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] col1, col2 = 렌더 시 readOnly=true (col2 만 readOnlyClass 미설정) / col3, col4 = 렌더 시 readOnly 미설정\n[현재] readOnlyClass = ' + lblClass + '\n[절차] 클래스 확인 -> 메소드로 읽기전용(col3 Column 단위, col4 Cell 단위) -> 읽기전용 해제(col1)\n[확인] 0 행 각 Cell 의 읽기전용 관련 클래스만 출력된다 (엔진 기본 클래스 제외)"', '', 'label1');

    // dataList 생성 (col1~col4 / 4행)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성
    let grp_comp = document.querySelector('.tc_group_basic');
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    strTarget += '<w2:gridView ' + strNameSpace + ' checkAllType="false" id="" style="width:600px;height:180px;" dataList="data:dlt_bind">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column1" value="col1 렌더readOnly"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column2" value="col2 렌더readOnly"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column3" value="col3 메소드Column"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="column4" value="col4 메소드Cell"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col1" value="" readOnly="true"' + attrClass + '></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col2" value="" readOnly="true"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col3" value=""' + attrClass + '></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="col4" value=""' + attrClass + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 0 행 특정 Column 의 Body Cell 에서 읽기전용 관련 클래스만 추출 (엔진 기본 클래스는 제외)
scwin.getReadOnlyClass = function (colIndex) {
    let td = document.querySelector("td[id*='target1_cell_0_" + colIndex + "']");
    if (!td) {
        return '(Cell 없음)';
    }
    let arr = td.className.split(/\s+/).filter(function (c) {
        return c === 'w2grid_default_readonly' || c.indexOf('rc_') === 0;
    });
    return arr.length ? arr.join(' ') : '없음';
}



// 각 Body Cell 의 읽기전용 클래스 확인
scwin.btn_checkClass_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.setReturnValue("col1 (렌더 readOnly + 클래스설정) : " + scwin.getReadOnlyClass(0));
    bottom.setReturnValue("col2 (렌더 readOnly + 클래스미설정) : " + scwin.getReadOnlyClass(1));
    bottom.setReturnValue("col3 (메소드 Column 읽기전용) : " + scwin.getReadOnlyClass(2));
    bottom.setReturnValue("col4 (메소드 Cell 읽기전용) : " + scwin.getReadOnlyClass(3));
}



// @spec1 : 메소드로 읽기전용 설정 (col3 = Column 단위, col4 = Cell 단위)
scwin.btn_setReadOnly_onclick = function () {
    target1.setColumnReadOnly("col3", true);
    target1.setCellReadOnly(0, "col4", true);

    scwin.btn_checkClass_onclick();
}



// @spec3 : 초기 렌더링 시 readOnly 였던 col1 의 읽기전용 상태를 해제 → 적용된 클래스 제거 확인
scwin.btn_releaseReadOnly_onclick = function () {
    target1.setColumnReadOnly("col1", false);

    scwin.btn_checkClass_onclick();
}
